/* ---------------------------------------------------------------------------
   View transitions

   Timing is deliberately asymmetric: old content leaves quickly so it stops
   competing for attention, new content arrives more gently and waits for the
   exit to finish before it becomes visible.
   --------------------------------------------------------------------------- */

:root {
  --duration-exit: 150ms;
  --duration-enter: 210ms;
  --duration-move: 400ms;
}

/* The transition overlay swallows pointer events by default, so clicks during
   an animation are lost. Let them through to the live page. */
::view-transition {
  pointer-events: none;
}

/* Shared element: grid thumbnail <-> detail hero (share="morph").
   The browser animates size and position on its own; the blur only hides
   pixel-level interpolation artifacts mid-flight. */
::view-transition-group(.morph) {
  animation-duration: var(--duration-move);
}
::view-transition-image-pair(.morph) {
  animation-name: via-blur;
}

/* Suspense reveal: the skeleton drops away, the real content rises in. */
::view-transition-old(.slide-down) {
  animation:
    var(--duration-exit) ease-out both fade reverse,
    var(--duration-exit) ease-out both slide-y reverse;
}
